 (1035, '数学', '三年级', '填空', 1, '{"stem": "下午 3 时用 24 时记时法表示是( )时。", "options": null}', '15', '下午 3 时过了中午 12 时，12+3=15，写作 15 时。', 'seed', '["practice", "VG-G3-5-1"]', NULL, 0),
 (1035, '数学', '三年级', '填空', 1, '{"stem": "20 时用普通记时法表示是晚上( )时。", "options": null}', '8', '24 时记时法超过 12 时就要减 12：20-12=8，所以 20 时是晚上 8 时。', 'seed', '["practice", "VG-G3-5-1"]', NULL, 0),
 (1035, '数学', '三年级', '选择', 2, '{"stem": "晚上 9 时用 24 时记时法表示是（ ）。", "options": ["① 9 时", "② 21 时", "③ 20 时"]}', '②', '晚上 9 时 = 12+9 = 21 时，写作 21 时。', 'seed', '["practice", "VG-G3-5-1"]', NULL, 0),
 (1035, '数学', '三年级', '判断', 2, '{"stem": "下午 2 时 30 分用 24 时记时法写作 2 时 30 分。（ ）", "options": null}', '错', '下午的时间要加 12，下午 2 时 30 分应写作 14 时 30 分，漏加 12 就错了。', 'seed', '["practice", "VG-G3-5-1"]', NULL, 0),
 (1035, '数学', '三年级', '判断', 2, '{"stem": "0 时表示半夜 12 时，是一天的开始。（ ）", "options": null}', '对', '一天从 0 时开始，0 时就是半夜 12 时，到 24 时一天结束。', 'seed', '["practice", "VG-G3-5-1"]', NULL, 0),
 (1036, '数学', '三年级', '选择', 2, '{"stem": "8 月有（ ）天。", "options": ["① 30 天", "② 31 天", "③ 28 天"]}', '②', '大月有 31 天。7 月、8 月是连续的两个大月，8 月有 31 天。', 'seed', '["diagnostic", "VG-G3-5-2"]', NULL, 0),
 (1036, '数学', '三年级', '填空', 1, '{"stem": "4 月有( )天。", "options": null}', '30', '小月有 30 天，4、6、9、11 月都是小月，4 月有 30 天。', 'seed', '["practice", "VG-G3-5-2"]', NULL, 0),
 (1036, '数学', '三年级', '判断', 2, '{"stem": "7 月和 8 月是连续的两个大月。（ ）", "options": null}', '对', '大月是 1、3、5、7、8、10、12 月，7 月和 8 月正好连着，都是大月。', 'seed', '["practice", "VG-G3-5-2"]', NULL, 0),
 (1036, '数学', '三年级', '判断', 2, '{"stem": "9 月有 31 天。（ ）", "options": null}', '错', '9 月是小月，只有 30 天。记小月口诀：四六九冬（11 月）三十整。', 'seed', '["practice", "VG-G3-5-2"]', NULL, 0),
 (1036, '数学', '三年级', '选择', 2, '{"stem": "下面各月中，大月是（ ）。", "options": ["① 6 月", "② 9 月", "③ 12 月"]}', '③', '12 月是大月有 31 天；6 月、9 月都是小月。', 'seed', '["practice", "VG-G3-5-2"]', NULL, 0),
 (1037, '数学', '三年级', '填空', 1, '{"stem": "平年 2 月有( )天。", "options": null}', '28', '平年 2 月有 28 天，全年 365 天。', 'seed', '["practice", "VG-G3-5-3"]', NULL, 0),
 (1037, '数学', '三年级', '判断', 1, '{"stem": "闰年 2 月有 29 天，全年有 366 天。（ ）", "options": null}', '对', '闰年 2 月多 1 天是 29 天，全年 366 天。', 'seed', '["practice", "VG-G3-5-3"]', NULL, 0),
 (1037, '数学', '三年级', '填空', 2, '{"stem": "平年全年有( )天。", "options": null}', '365', '平年 2 月 28 天，全年 365 天；闰年 366 天。', 'seed', '["practice", "VG-G3-5-3"]', NULL, 0),
 (1037, '数学', '三年级', '判断', 3, '{"stem": "1900 年是闰年。（ ）", "options": null}', '错', '整百年必须是 400 的倍数才是闰年。1900÷400 有余数，所以 1900 年是平年，不是闰年。', 'seed', '["practice", "VG-G3-5-3"]', NULL, 0),
 (1037, '数学', '三年级', '选择', 2, '{"stem": "通常每（ ）年有一个闰年。", "options": ["① 3 年", "② 4 年", "③ 5 年"]}', '②', '通常 4 年一闰，公历年份是 4 的倍数的一般是闰年。', 'seed', '["practice", "VG-G3-5-3"]', NULL, 0),
 (1038, '数学', '三年级', '选择', 2, '{"stem": "今天是星期三，7 天后是（ ）。", "options": ["① 星期二", "② 星期三", "③ 星期四"]}', '②', '一个星期有 7 天，过了 7 天正好又回到星期三。', 'seed', '["practice", "VG-G3-5-4"]', NULL, 0),
 (1038, '数学', '三年级', '应用题', 2, '{"stem": "今天是星期三，再过 15 天是星期几？", "options": null}', '星期四', '15÷7 = 2（周）……1（天），余 1 天就在星期三后面数 1 天，是星期四。', 'seed', '["practice", "VG-G3-5-4"]', NULL, 0),
 (1038, '数学', '三年级', '应用题', 3, '{"stem": "某月 1 日是星期五，这个月 22 日是星期几？", "options": null}', '星期五', '22-1=21（天），21÷7=3（周），正好 3 周，所以 22 日和 1 日一样是星期五。', 'seed', '["practice", "VG-G3-5-4"]', NULL, 0),
 (1038, '数学', '三年级', '应用题', 3, '{"stem": "7 月 1 日是星期一，7 月 31 日是星期几？", "options": null}', '星期三', '31-1=30（天），30÷7=4（周）……2（天），余 2 天在星期一后面数 2 天，是星期三。', 'seed', '["practice", "VG-G3-5-4"]', NULL, 0),
 (1038, '数学', '三年级', '判断', 3, '{"stem": "某月 1 日是星期六，这个月的 8 日一定也是星期六。（ ）", "options": null}', '对', '8 日比 1 日晚 7 天，正好一个星期，所以还是星期六。', 'seed', '["practice", "VG-G3-5-4"]', NULL, 0),
 (1045, '数学', '三年级', '填空', 1, '{"stem": "1 千米 = ( )米。", "options": null}', '1000', '千米是比米大的长度单位，1 千米 = 1000 米。', 'seed', '["practice", "VG-G3-7-1"]', NULL, 0),
 (1045, '数学', '三年级', '判断', 2, '{"stem": "汽车在高速公路上每小时大约行驶 80 千米。（ ）", "options": null}', '对', '汽车速度很快，用千米作单位合适，每小时约 80 千米符合实际。', 'seed', '["practice", "VG-G3-7-1"]', NULL, 0),
 (1045, '数学', '三年级', '填空', 2, '{"stem": "3 千米 = ( )米。", "options": null}', '3000', '1 千米 = 1000 米，3 千米 = 3000 米。', 'seed', '["practice", "VG-G3-7-1"]', NULL, 0),
 (1045, '数学', '三年级', '选择', 2, '{"stem": "马拉松比赛全程大约是 42（ ）。", "options": ["① 米", "② 千米", "③ 分米"]}', '②', '马拉松全程约 42 千米（42.195 千米），用千米作单位。', 'seed', '["practice", "VG-G3-7-1"]', NULL, 0),
 (1045, '数学', '三年级', '判断', 2, '{"stem": "教室的长大约是 8 千米。（ ）", "options": null}', '错', '教室长一般只有 8 米左右，8 千米太长了，应该是 8 米。', 'seed', '["practice", "VG-G3-7-1"]', NULL, 0),
 (1046, '数学', '三年级', '应用题', 2, '{"stem": "小明家到学校 2 千米，他每天上学、放学往返一次，一天一共走多少米？", "options": null}', '4000米', '往返一次要走 2 个 2 千米：2×2=4（千米），4 千米 = 4000 米。注意问题问的是“米”。', 'seed', '["practice", "VG-G3-7-2"]', NULL, 0),
 (1046, '数学', '三年级', '应用题', 2, '{"stem": "体育老师每天晨跑 3 千米，一周（5 天）共跑多少千米？", "options": null}', '15千米', '每天 3 千米，5 天共 3×5=15（千米）。', 'seed', '["practice", "VG-G3-7-2"]', NULL, 0),
 (1046, '数学', '三年级', '应用题', 3, '{"stem": "小华每分钟走 90 米，20 分钟一共走多少米？", "options": null}', '1800米', '每分钟 90 米，20 分钟走 90×20=1800（米）。', 'seed', '["practice", "VG-G3-7-2"]', NULL, 0),
 (1046, '数学', '三年级', '选择', 3, '{"stem": "学校操场跑道一圈 400 米，跑 5 圈是（ ）。", "options": ["① 2 米", "② 2 千米", "③ 200 米"]}', '②', '400×5=2000（米），2000 米 = 2 千米。', 'seed', '["practice", "VG-G3-7-2"]', NULL, 0),
 (1046, '数学', '三年级', '判断', 3, '{"stem": "小红家离学校 1 千米，小刚家离学校 800 米，小刚家离学校近。（ ）", "options": null}', '对', '比较前先统一单位：1 千米 = 1000 米，1000 米 > 800 米，所以小刚家近。', 'seed', '["practice", "VG-G3-7-2"]', NULL, 0),
 (1047, '数学', '三年级', '填空', 2, '{"stem": "一副七巧板有( )块。", "options": null}', '7', '一副七巧板由 7 块板组成，所以叫“七巧板”。', 'seed', '["practice", "VG-G3-8-1"]', NULL, 0),
 (1047, '数学', '三年级', '填空', 2, '{"stem": "七巧板中有( )个三角形。", "options": null}', '5', '七巧板由 5 个三角形、1 个正方形和 1 个平行四边形组成，共 7 块。', 'seed', '["practice", "VG-G3-8-1"]', NULL, 0),
 (1047, '数学', '三年级', '判断', 2, '{"stem": "七巧板由 1 个正方形、1 个平行四边形和 5 个三角形组成。（ ）", "options": null}', '对', '七巧板共 7 块：5 个三角形、1 个正方形、1 个平行四边形。', 'seed', '["practice", "VG-G3-8-1"]', NULL, 0),
 (1047, '数学', '三年级', '判断', 3, '{"stem": "七巧板中任意两块三角形都能拼成一个正方形。（ ）", "options": null}', '错', '只有两块完全一样的三角形（如两块小三角形）才能拼成正方形，大小不同的三角形拼不成。', 'seed', '["practice", "VG-G3-8-1"]', NULL, 0),
 (1047, '数学', '三年级', '选择', 2, '{"stem": "下面说法正确的是（ ）。", "options": ["① 七巧板一共有 6 块", "② 七巧板里有圆形", "③ 用七巧板能拼出很多有趣的图形"]}', '③', '七巧板能拼出各种有趣的图形，是我国的传统智力玩具。七巧板没有圆，也不只有 6 块。', 'seed', '["practice", "VG-G3-8-1"]', NULL, 0),
 (1048, '数学', '三年级', '应用题', 2, '{"stem": "一块长方形菜地长 10 米、宽 6 米，四周都围上篱笆，需要篱笆多少米？", "options": null}', '32米', '四周都围就是求周长：（10+6）×2=32（米）。', 'seed', '["practice", "VG-G3-8-2"]', NULL, 0),
 (1048, '数学', '三年级', '应用题', 3, '{"stem": "一块长方形菜地长 10 米、宽 6 米，相邻两面靠墙（占一个墙角），只需围两面，需要篱笆多少米？", "options": null}', '16米', '相邻两面靠墙，只要围剩下的两条边：10+6=16（米）。', 'seed', '["practice", "VG-G3-8-2"]', NULL, 0),
 (1048, '数学', '三年级', '应用题', 3, '{"stem": "一块长方形菜地一面靠墙（宽边靠墙），围篱笆一共用了 22 米，菜地的宽是 6 米，长是多少米？", "options": null}', '8米', '宽边靠墙，篱笆 = 2 条长 + 1 条宽：22-6=16（米）是两条长，长 = 16÷2=8（米）。', 'seed', '["practice", "VG-G3-8-2"]', NULL, 0),
 (1048, '数学', '三年级', '选择', 3, '{"stem": "用 24 米长的篱笆围一个正方形鸡舍（不靠墙），鸡舍的边长是（ ）。", "options": ["① 4 米", "② 6 米", "③ 8 米"]}', '②', '正方形周长 = 边长×4，边长 = 24÷4=6（米）。', 'seed', '["practice", "VG-G3-8-2"]', NULL, 0),
 (1048, '数学', '三年级', '判断', 3, '{"stem": "一块长方形菜地长 8 米、宽 5 米，一面靠墙围篱笆，至少需要 21 米。（ ）", "options": null}', '错', '“至少”要让长边靠墙，只围两条宽和一条长：5×2+8=18（米）。21 米是按宽边靠墙算的，不是最少。', 'seed', '["practice", "VG-G3-8-2"]', NULL, 0);
